<?php
require_once __DIR__ . '/../includes/functions.php';require_admin();$pageTitle='Бронирования — Лесная гавань';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['booking_id']??0);$status=$_POST['status']??'';$allowed=['pending','confirmed','completed','cancelled'];if(in_array($status,$allowed,true)){$st=$pdo->prepare('UPDATE bookings SET status=? WHERE id=?');$st->execute([$status,$id]);set_flash('Статус бронирования изменён.');}redirect('/admin/bookings.php');}
$items=$pdo->query('SELECT b.*,u.full_name,u.email,u.phone,a.title FROM bookings b JOIN users u ON u.id=b.user_id JOIN accommodations a ON a.id=b.accommodation_id ORDER BY b.created_at DESC')->fetchAll();include __DIR__.'/../includes/header.php';
?>
<section class="container admin-page"><div class="admin-heading"><div><span class="eyebrow">ЗАЯВКИ ГОСТЕЙ</span><h1>Все бронирования</h1><p>Проверка заявок и изменение их статуса.</p></div><a class="btn btn-outline-green" href="<?= BASE_URL ?>/admin/">← К статистике</a></div><div class="admin-table-wrap"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>№</th><th>Гость</th><th>Вариант</th><th>Даты</th><th>Гостей</th><th>Стоимость</th><th>Статус</th><th>Изменить</th></tr></thead><tbody><?php foreach($items as $b): ?><tr><td>#<?= (int)$b['id'] ?></td><td><strong><?= e($b['full_name']) ?></strong><small><?= e($b['phone']) ?><br><?= e($b['email']) ?></small></td><td><?= e($b['title']) ?></td><td><?= date('d.m.Y',strtotime($b['check_in'])) ?> – <?= date('d.m.Y',strtotime($b['check_out'])) ?></td><td><?= (int)$b['guests'] ?></td><td><?= number_format((float)$b['total_price'],0,',',' ') ?> ₽</td><td><span class="status-pill <?= e(booking_status_class($b['status'])) ?>"><?= e(booking_status_label($b['status'])) ?></span></td><td><form method="post" class="status-form"><?= csrf_field() ?><input type="hidden" name="booking_id" value="<?= (int)$b['id'] ?>"><select class="form-select form-select-sm" name="status"><option value="pending" <?= $b['status']==='pending'?'selected':'' ?>>Ожидает</option><option value="confirmed" <?= $b['status']==='confirmed'?'selected':'' ?>>Подтверждена</option><option value="completed" <?= $b['status']==='completed'?'selected':'' ?>>Завершена</option><option value="cancelled" <?= $b['status']==='cancelled'?'selected':'' ?>>Отменена</option></select><button class="btn btn-green btn-sm">Сохранить</button></form></td></tr><?php endforeach; ?><?php if(!$items): ?><tr><td colspan="8" class="text-center text-muted py-5">Бронирований пока нет.</td></tr><?php endif; ?></tbody></table></div></div></section>
